"""Human-readable date rendering for TTDL table date columns."""
from __future__ import annotations

from datetime import date


def human_date(value: str, *, today: date | None = None, compact: bool = False) -> str:
    """Format an ISO date relative to today using TTDL's d/w/m/y units."""
    if not value:
        return ""
    target = date.fromisoformat(value)
    today = today or date.today()
    delta = (target - today).days
    if delta == 0:
        return "today"
    distance = abs(delta)
    if distance < 7:
        amount, unit = distance, "d"
    elif distance < 30:
        amount, unit = distance // 7, "w"
    elif distance < 365:
        amount, unit = distance // 30, "m"
    else:
        amount, unit = distance // 365, "y"
    result = f"{amount}{unit}"
    if compact:
        return result
    return f"in {result}" if delta > 0 else f"{result} ago"
