from __future__ import annotations

from datetime import date, timedelta
import re

DEFAULT_MARKS = "┌│└╎╎─[~~"


def _minutes(value: str) -> int | None:
    s = value.strip().lower()
    am = s.endswith("am")
    pm = s.endswith("pm")
    if am or pm:
        s = s[:-2]
    if not s.isdigit():
        return None
    n = int(s)
    hour, minute = divmod(n, 100)
    if hour > 24 or minute >= 60 or (hour == 24 and minute):
        return None
    if am or pm:
        if hour < 1 or hour > 12: return None
        hour = hour % 12 + (12 if pm else 0)
    return hour * 60 + minute


def _time_range(value: str) -> tuple[int, int]:
    sep = ".." if ".." in value else "-"
    if sep in value:
        left, right = value.split(sep, 1)
    else:
        left, right = value, ""
    start = _minutes(left) if left else 0
    end = _minutes(right) if right else 24 * 60
    if start is None or end is None:
        raise ValueError("invalid agenda time range")
    return start, end


def _values(task: dict, name: str) -> list[str]:
    value = task.get("tags", {}).get(name, [])
    if isinstance(value, str): return [value]
    return [str(x) for x in value]


def _task_day(task: dict, fields: tuple[str, ...]) -> str | None:
    for field in fields:
        val = task.get(field)
        if not val:
            vals = _values(task, field)
            val = vals[0] if vals else None
        if val: return str(val)
    return None


def _clock(minutes: int) -> str:
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


def _time_tag(value: str) -> tuple[int, int | None] | None:
    start, sep, end = value.partition("-")
    a = _minutes(start)
    b = _minutes(end) if sep and end else None
    if a is None or (sep and end and b is None): return None
    if b is not None and b <= a: b = None
    return a, b


def render_agenda(tasks: list[dict], on: str | date | None = None,
                  fields: str | tuple[str, ...] = "due", time_range: str = "800-2000",
                  slot: int = 30, hide_all_day: bool = False,
                  marks: str = DEFAULT_MARKS) -> str:
    """Render one day's agenda; each input task is a parser-derived mapping.

    `time_range` accepts HHMM-HHMM (including an open end); `slot` is minutes.
    """
    if slot < 15 or slot > 1440 or len(marks) != 9:
        raise ValueError("invalid agenda slot or marks")
    selected_day = on.isoformat() if isinstance(on, date) else (on or date.today().isoformat())
    field_names = tuple(x.strip() for x in (fields.split(",") if isinstance(fields, str) else fields) if x.strip())
    start, end = _time_range(time_range)
    if end <= start: raise ValueError("invalid agenda time range")
    all_day, timed = [], []
    for task in tasks:
        if task.get("done") or _task_day(task, field_names) != selected_day: continue
        tags = _values(task, "time")
        subject = str(task.get("subject") or task.get("raw") or "")
        ident = task.get("id", "")
        if not tags:
            all_day.append((ident, subject)); continue
        interval = _time_tag(tags[0])
        if interval is None: continue
        a, b = interval
        visible_end = b if b is not None else end
        if visible_end <= start or a >= end: continue
        original_start, original_end = a, visible_end
        if a < start: a = start
        if visible_end > end: visible_end = end
        timed.append({"id": ident, "text": subject, "start": a, "end": visible_end,
                      "original_start": original_start, "original_end": original_end,
                      "unlimited": b is None})
    timed.sort(key=lambda x: (x["start"], x["id"]))

    # Allocate stable lanes, reusing a lane once its prior task has finished.
    lane_ends: list[int] = []
    for item in timed:
        lane = next((i for i, e in enumerate(lane_ends) if e <= item["start"]), len(lane_ends))
        occupied_until = min(item["end"], item["start"] + slot) if item["unlimited"] else item["end"]
        if lane == len(lane_ends): lane_ends.append(occupied_until)
        else: lane_ends[lane] = occupied_until
        item["lane"] = lane

    out: list[str] = []
    slots = list(range(start, end + 1, slot))
    if not slots or slots[-1] != end: slots.append(end)
    for minute in slots:
        marks_for_row = [" "] * len(lane_ends)
        labels = []
        for item in timed:
            a, b, lane = item["start"], item["end"], item["lane"]
            slot_end = min(minute + slot, end)
            ends_on_boundary = b == minute and a < b
            intersects = (a < slot_end and b > minute) or ends_on_boundary
            if not intersects: continue
            starts_here = ((item["original_start"] >= minute and item["original_start"] < slot_end)
                           or (minute == start and item["original_start"] < start))
            ends_here = b > minute and b < slot_end
            if item["unlimited"] and starts_here:
                mark = marks[6]
            elif item["unlimited"]:
                mark = " "
            elif minute == start and item["original_start"] < start:
                mark = marks[3]
            elif slot_end == end and minute == end and item["original_end"] > end:
                mark = marks[4]
            elif starts_here and ends_here:
                mark = marks[5]
            elif starts_here:
                mark = marks[0] if a == minute else marks[7]
            elif ends_on_boundary and item["original_end"] <= end:
                mark = marks[2]
            elif ends_here:
                mark = marks[2] if b == slot_end else marks[8]
            elif minute == start and item["original_start"] < start:
                mark = marks[3]
            elif minute == end and item["original_end"] > end:
                mark = marks[4]
            else:
                mark = marks[1]
            marks_for_row[lane] = mark
            if starts_here:
                labels.append((lane, f"{item['id']}.{item['text']}"))
        row = _clock(minute)
        if lane_ends:
            marker_text = "".join(marks_for_row)
            row += " " + marker_text.rstrip()
            if labels:
                row += " " + "  ".join(text for _, text in sorted(labels))
            elif marker_text.strip():
                row += " "
            else:
                row += marker_text
        out.append(row)
    if not hide_all_day and all_day:
        out.extend(["", "All day:"])
        for ident, subject in sorted(all_day, key=lambda x: x[0]):
            out.append(f"{ident}.{subject}" if ident != "" else subject)
    return "\n".join(out)
