    elif field=='ctx': value=record.get('contexts') or []
    elif field=='hashtag': value=record.get('hashtag') or []
    elif field=='done': value='x' if record.get('done') else ''
    elif field in record: value=record.get(field)
    else:
        tags=record.get('tags') or {}
        value=tags.get(field,'')
    if isinstance(value,(list,tuple,set)):
        return (not bool(value),tuple(str(x).casefold() for x in sorted(value,key=str.casefold)))
    text=str(value or '')
    return (not bool(text),text.casefold())

def sort_records(rows, fields=None):
